import org.mockito.MockitoAnnotations;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import static org.mockito.Mockito.when;

public class DatasetUtilities_iterateRangeBounds_TriageGen2Test {

    @Mock
    private XYDataset mockXYDataset;

    @Mock
    private IntervalXYDataset mockIntervalDataset;

    @Mock
    private OHLCDataset mockOHLCDataset;

    public DatasetUtilities_iterateRangeBounds_TriageGen2Test() {
        MockitoAnnotations.openMocks(this);
    }

    @Test
    public void testIterateRangeBounds_StandardDataset_IncludeIntervalFalse() {
        when(mockXYDataset.getSeriesCount()).thenReturn(1);
        when(mockXYDataset.getItemCount(0)).thenReturn(2);
        when(mockXYDataset.getYValue(0, 0)).thenReturn(10.0);
        when(mockXYDataset.getYValue(0, 1)).thenReturn(20.0);

        Range result = DatasetUtilities.iterateRangeBounds(mockXYDataset, false);

        assertEquals(10.0, result.getLower(), 1e-10);
        assertEquals(20.0, result.getUpper(), 1e-10);
    }

    @Test
    public void testIterateRangeBounds_StandardDataset_WithNaN() {
        when(mockXYDataset.getSeriesCount()).thenReturn(1);
        when(mockXYDataset.getItemCount(0)).thenReturn(3);
        when(mockXYDataset.getYValue(0, 0)).thenReturn(5.0);
        when(mockXYDataset.getYValue(0, 1)).thenReturn(Double.NaN);
        when(mockXYDataset.getYValue(0, 2)).thenReturn(15.0);

        Range result = DatasetUtilities.iterateRangeBounds(mockXYDataset, false);

        assertEquals(5.0, result.getLower(), 1e-10);
        assertEquals(15.0, result.getUpper(), 1e-10);
    }

    @Test
    public void testIterateRangeBounds_IntervalDataset_IncludeIntervalTrue() {
        when(mockIntervalDataset.getSeriesCount()).thenReturn(1);
        when(mockIntervalDataset.getItemCount(0)).thenReturn(1);
        when(mockIntervalDataset.getStartYValue(0, 0)).thenReturn(1.0);
        when(mockIntervalDataset.getEndYValue(0, 0)).thenReturn(5.0);

        Range result = DatasetUtilities.iterateRangeBounds(mockIntervalDataset, true);

        assertEquals(1.0, result.getLower(), 1e-10);
        assertEquals(5.0, result.getUpper(), 1e-10);
    }

    @Test
    public void testIterateRangeBounds_IntervalDataset_WithNaN() {
        when(mockIntervalDataset.getSeriesCount()).thenReturn(1);
        when(mockIntervalDataset.getItemCount(0)).thenReturn(2);
        // Item 1: valid
        when(mockIntervalDataset.getStartYValue(0, 0)).thenReturn(2.0);
        when(mockIntervalDataset.getEndYValue(0, 0)).thenReturn(4.0);
        // Item 2: NaN values
        when(mockIntervalDataset.getStartYValue(0, 1)).thenReturn(Double.NaN);
        when(mockIntervalDataset.getEndYValue(0, 1)).thenReturn(Double.NaN);

        Range result = DatasetUtilities.iterateRangeBounds(mockIntervalDataset, true);

        assertEquals(2.0, result.getLower(), 1e-10);
        assertEquals(4.0, result.getUpper(), 1e-10);
    }

    @Test
    public void testIterateRangeBounds_OHLCDataset_IncludeIntervalTrue() {
        when(mockOHLCDataset.getSeriesCount()).thenReturn(1);
        when(mockOHLCDataset.getItemCount(0)).thenReturn(1);
        when(mockOHLCDataset.getLowValue(0, 0)).thenReturn(100.0);
        when(mockOHLCDataset.getHighValue(0, 0)).thenReturn(200.0);

        Range result = DatasetUtilities.iterateRangeBounds(mockOHLCDataset, true);

        assertEquals(100.0, result.getLower(), 1e-10);
        assertEquals(200.0, result.getUpper(), 1e-10);
    }

    @Test
    public void testIterateRangeBounds_OHLCDataset_WithNaN() {
        when(mockOHLCDataset.getSeriesCount()).thenReturn(1);
        when(mockOHLCDataset.getItemCount(0)).thenReturn(2);
        // Item 1: valid
        when(mockOHLCDataset.getLowValue(0, 0)).thenReturn(50.0);
        when(mockOHLCDataset.getHighValue(0, 0)).thenReturn(150.0);
        // Item 2: one NaN
        when(mockOHLCDataset.getLowValue(0, 1)).thenReturn(Double.NaN);
        when(mockOHLCDataset.getHighValue(0, 1)).thenReturn(300.0);

        Range result = DatasetUtilities.iterateRangeBounds(mockOHLCDataset, true);

        assertEquals(50.0, result.getLower(), 1e-10);
        assertEquals(300.0, result.getUpper(), 1e-10);
    }

    @Test
    public void testIterateRangeBounds_EmptyDataset() {
        when(mockXYDataset.getSeriesCount()).thenReturn(0);
        Range result = DatasetUtilities.iterateRangeBounds(mockXYDataset, false);
        assertNull(result);
    }

    @Test
    public void testIterateRangeBounds_DatasetWithOnlyNaN() {
        when(mockXYDataset.getSeriesCount()).thenReturn(1);
        when(mockXYDataset.getItemCount(0)).thenReturn(1);
        when(mockXYDataset.getYValue(0, 0)).thenReturn(Double.NaN);

        Range result = DatasetUtilities.iterateRangeBounds(mockXYDataset, false);
        assertNull(result);
    }

    @Test
    public void testIterateRangeBounds_IntervalDataset_IncludeIntervalFalse_FallsToStandard() {
        // When includeInterval is false, even if it is an IntervalXYDataset, it should use getYValue
        when(mockIntervalDataset.getSeriesCount()).thenReturn(1);
        when(mockIntervalDataset.getItemCount(0)).thenReturn(1);
        // Note: In standard case it calls getYValue, not getStartY/EndY
        when(mockIntervalDataset.getYValue(0, 0)).thenReturn(10.0);

        Range result = DatasetUtilities.iterateRangeBounds(mockIntervalDataset, false);

        assertEquals(10.0, result.getLower(), 1e-10);
        assertEquals(10.0, result.getUpper(), 1e-10);
    }
}
